<?php require_once "../config/auth.php";require_admin();$p=db();if($_SERVER["REQUEST_METHOD"]==="POST"){check_csrf();if($_POST["action"]==="add")$p->prepare("INSERT INTO services(category,name,rate_per_1000,min_qty,max_qty) VALUES(?,?,?,?,?)")->execute([trim($_POST["category"]),trim($_POST["name"]),(float)$_POST["rate"],(int)$_POST["min"],(int)$_POST["max"]]);else$p->prepare("UPDATE services SET status=IF(status='active','inactive','active') WHERE id=?")->execute([(int)$_POST["id"]]);}$rows=$p->query("SELECT * FROM services ORDER BY category,name")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../public/style.css"></head><body><main><h1>Services</h1><form class="card" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input name="category" placeholder="Category" required><input name="name" placeholder="Service name" required><input name="rate" type="number" step=".0001" placeholder="Rate per 1000" required><input name="min" type="number" value="100" required><input name="max" type="number" value="100000" required><button name="action" value="add">Add Service</button></form><div class="table"><table><tr><th>ID</th><th>Category</th><th>Name</th><th>Rate</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=$r["id"]?></td><td><?=e($r["category"])?></td><td><?=e($r["name"])?></td><td><?=$r["rate_per_1000"]?></td><td><?=$r["status"]?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r["id"]?>"><button>Toggle</button></form></td></tr><?php endforeach;?></table></div></main></body></html>